(894, 'pasword_hint', 'At least 1 capital, 1 lowercase, 1 number and more than 8 characters long', 'At least 1 capital, 1 lowercase, 1 number and more than 8 characters long', 'At least 1 capital, 1 lowercase, 1 number and more than 8 characters long', 'At least 1 capital, 1 lowercase, 1 number and more than 8 characters long', 'At least 1 capital, 1 lowercase, 1 number and more than 8 characters long'),
(895, 'reset_password', 'កំណត់ឡើងវិញ​ពាក្យ​សម្ងាត់​', 'Reset Password', '重设密码', 'ตั้งค่ารหัสผ่าน', 'Đặt lại mật khẩu'),
(896, 'reset_password_link_alt', 'អ្នក​អាច​បិទ​ភ្ជាប់​កូដ​នេះ​ដូច​ខាង​ក្រោម​នៅ​ក្នុង URL របស់​អ្នក​ប្រសិន​បើ​តំណ​ខាង​លើ​នេះ​មិន​ត្រូវ​បាន​ធ្វើ​', 'You can paste this code below in your url if the above link not working', '如果上面的链接无效，请复制下面的网址至您的浏览器。', 'คุณสามารถ วางโค้ด ด้านล่างนี้ ใน URL ของคุณถ้าลิงค์ด้านบน ไม่ทำงาน', 'Bạn có thể dán mã này dưới đây trong url của bạn nếu liên kết trên không làm việc'),
(897, 'email_forgotten_password_subject', 'កំណត់​ឡើង​វិញ​លម្អិត​ពាក្យ​សម្ងាត់​', 'Reset Password Details', '重置密码内容', 'ตั้งค่ารายละเอียดรหัสผ่าน', 'Chi tiết đặt lại mật khẩu'),
(898, 'reset_password_email', 'កំណត់​ឡើង​វិញ​​ពាក្យ​សម្ងាត់​ \%s', 'Reset password for \%s', '重设密码 \%s', 'ตั้งค่ารหัสผ่านของ \%', 'Đặt lại mật khẩu \%s'),
(899, 'back_to_login', 'ត្រឡប់​ដើម្បី​ចូលកម្មវិធីវិញ​', 'Back to login', '返回登入', 'กลับเพื่อลงชื่อใช้งาน', 'Quay lại đăng nhập'),
(900, 'forgot_password_unsuccessful', 'កំណត់​ឡើង​វិញ​ជា​ពាក្យ​សម្ងាត់​បាន​បរាជ័យ​', 'Reset password failed', '重设密码失败', 'การตั้งค่ารหัสผ่านผิดพลาด', 'Đặt lại mật khẩu đã thất bại');
INSERT INTO `aura_language` (`id`, `code`, `khmer`, `english`, `chinese`, `thai`, `vietnamese`) VALUES
(901, 'forgot_password_successful', 'ពាក្យ​សម្ងាត់​ដោយ​ជោគជ័យ​បាន​កំណត់​ឡើងវិញ​, សូម​ប្រើ​ពាក្យ​សម្ងាត់​ថ្មី​ដើម្បី​ចូលកម្មវិធី​', 'Email has been sent with reset password instructions', '密码重置成功，请使用新密码登入', 'ตั้งค่ารหัสผ่านเรียบร้อยแล้ว โปรดใช้รหัสผ่านใหม่ในการลงชื่อเข้าใช้', 'Thiết lập lại mật khẩu thành công, hãy sử dụng mật khẩu mới để đăng nhập'),
(902, 'password_change_unsuccessful', 'Action Failed! unable to change password.', 'Action Failed! unable to change password.', 'Action Failed! unable to change password.', 'Action Failed! unable to change password.', 'Action Failed! unable to change password.'),
(903, 'password_change_successful', 'ពាក្យ​សម្ងាត់​ផ្លាស់​ប្តូ​រ​បាន​ដោយ​ជោគជ័យ​', 'Password successfully changed', '密码变更成功', 'เปลี่ยนรหัสผ่านเรียบร้อยแล้ว', 'Đổi mật khẩu thành công'),
(904, 'forgot_password_email_not_found', 'អាសយដ្ឋាន​អ៊ីមែល​ដែល​បាន​បញ្ចូល​មិន​មែន​ជា​របស់​គណនី​ណា​មួយ​', 'The email address enter does not belong to any account.', '输入的电子邮件地址不属於任何帐户。', 'ใส่ที่อยู่อีเมลล์ ที่ไม่เคยใช้กับผู้ใช้อื่นๆ.', 'The email address enter does not belong to any account.'),
(905, 'login_unsuccessful', 'Login Failed, Please double check username and password before trying again', 'Login Failed, Please double check username and password before trying again', 'Login Failed, Please double check username and password before trying again', 'Login Failed, Please double check username and password before trying again', 'Login Failed, Please double check username and password before trying again'),
(906, 'email_forgot_password_link', 'ចុច LINK ដើម្បីកំណត់​ឡើងវិញពាក្យ​សម្ងាត់​', 'Reset Password Link', '重设密码连结', 'ตั้งค่ารหัสผ่าน ผ่านลิ้งค์', 'Đặt lại Mật khẩu Liên kết'),
(907, 'reset_password_heading', 'កំណត់ឡើងវិញ​ពាក្យ​សម្ងាត់​', 'Reset Password', '重设密码', 'ตั้งค่ารหัสผ่าน', 'Đặt lại mật khẩu'),
(908, 'reset_password_new_password_label', 'ដាក់ពាក្យ​សម្ងាត់​ថ្មី', 'New Password', '新密码', 'รหัสผ่านใหม่', 'Mật khẩu mới'),
(909, 'reset_password_new_password_confirm_label', 'បញ្ជាក់​ពាក្យ​សម្ងាត់​ថ្មី​', 'Confirm New Password', '确认新密码', 'ยืนยันรหัสผ่านใหม่', 'Xác nhận mật khẩu mới'),
