(912, 'reset_password_submit_btn', 'កំណត់ឡើងវិញ​ពាក្យ​សម្ងាត់​', 'Reset Password', '重设密码', 'ตั้งค่ารหัสผ่าน', 'Đặt lại mật khẩu'),
