(2234, 'pos_setting_updated_payment_failed', 'POS ការកំណត់កម្មវិធី រក្សាទុកទិន្នន័យបានជោគជ័យ ប៉ុន្តែការកំណត់ការបង់លុយតាមប្រព័ន្ធមិនជោគជ័យ. សូមសាក់ល្បងម្តងទៀត', 'POS settings successfully saved but payment gateways settings failed. Please try again', 'POS设定成功储存，但是付款方式设定失败，请重试。', 'การตั้งค่า ณ จุดขายเรียบร้อยแล้ว แต่การตั้งค่าเกตท์เวย์ล้มเหลว โปรดลองใหม่ภายหลัง', 'POS settings successfully saved but payment gateways settings failed. Please try again'),
(2235, 'tax_request_failed', 'សំណើបានបរាជ័យ, មានបញ្ហាខ្លះនៅក្នុងប្រអប់អត្រាការកំណត់ចំនួនពន្ធ!', 'Request Failed, There is some problem with tax rate!', '请求失败，税率有一些问题！', 'พบปัญกาการขอภาษี!', 'Request Failed, There is some problem with tax rate!'),
(2236, 'pos_error', 'មានកំហុសឆ្គងក្នុងការគណនា. សូមបន្ថែមផលិតផលម្តងទៀត. អរគុណ!', 'An error occurred in the calculation. Please add products again. Thank you!', '在计算时发生错误。请重新加入产品。谢谢！', 'เกิดข้อผิดพลาด ในการประมวลผล กรุณาเพิ่ม ผลิตภัณฑ์ อีกครั้ง ขอบคุณ!', 'An error occurred in the calculation. Please add products again. Thank you!'),
(2237, 'qty_limit', 'បរិមាណកំណត់មិន​អោយលើសពី 999.', 'You have reached the quantity limit 999.', '您已经达到了数量999的限制。', 'สินค้าคุณถึงขีด จำกัด ปริมาณ 999.', 'You have reached the quantity limit 999.'),
(2238, 'max_pro_reached', 'អតិបរមាដែលត្រូវបានអនុញ្ញាតទាក់ទងសូមបន្ថែមការបង់ប្រាក់សម្រាប់ការនេះនិងបើកច្បាប់ថ្មីសម្រាប់ធាតុក្រោយទាំងអស់គ្នាសូមអរគុណ!', 'Max Allowed Reached! Please add payment for this and open new bill for all next items. Thank you!', '达到允许的最大数量！请新增付款，其馀品项请开启新的帐单处理。谢谢！', 'กรุณาเพิ่ม การชำระเงินนี้และ เปิด เรียกเก็บเงินใหม่ สำหรับรายการ ต่อไป ทั้งหมด ขอบคุณ!', 'Max Allowed Reached! Please add payment for this and open new bill for all next items. Thank you!'),
(2239, 'code_error', 'សំណើបានបរាជ័យ, សូមពិនិត្យមើលកូដរបស់អ្នកនិងព្យាយាមម្ដងទៀត!', 'Request Failed, Please check your code and try again!', '请求失败，请检查你的代码，然後再试一次！', 'การร้องขอ ล้มเหลว โปรดตรวจสอบ รหัสของคุณ และลองอีกครั้ง!', 'Request Failed, Please check your code and try again!'),
(2240, 'x_total', 'សូមបន្ថែមផលិតផលមុនការទូទាត់សូមអរគុណ!', 'Please add product before payment. Thank you!', '付款前请先加入产品。谢谢！', 'กรุณาเพิ่ม สินค้า ก่อนการชำระเงิน ขอบคุณ!', 'Please add product before payment. Thank you!'),
(2241, 'paid_l_t_payable', 'ចំនួនទឹកប្រាក់ដែលបង់ប្រាក់គឺតិចជាងចំនួនត្រូវបង់នោះសូមចុចយល់ព្រមដើម្បីដាក់ជូនការលក់។', 'Paid amount is less than the payable amount. Please press OK to submit the sale.', '支付的金额小於应付金额。请按ＯＫ储存销售。', 'จำนวนเงินที่จ่าย น้อยกว่า จำนวนเงินที่จ่าย กรุณากด ตกลงเพื่อ ส่ง ขาย.', 'Paid amount is less than the payable amount. Please press OK to submit the sale.'),
(2242, 'suspended_sales', 'ការលក់បានបន្ទប់ | តុ', 'Suspended Sales', '暂缓销售', 'การขายถูกระงับ', 'Suspended Sales'),
(2243, 'sale_suspended', 'លក់បានបន្ទប់ | តុដោយជោគជ័យ', 'Sale Successfully Suspended.', '销售暂缓成功', 'การขายถูกระงับสำเร็จแล้ว.', 'Sale Successfully Suspended.'),
(2244, 'sale_suspend_failed', 'បន្ទប់ | តុលក់បរាជ័យ សូមព្យាយាមម្ដងទៀត!', 'Suspend Sale Failed. Please try again!', '暂缓销售失败。请再试一次！', 'การขายถูกระงับ กรุณาลองใหม่อีกครั้ง!', 'Suspend Sale Failed. Please try again!'),
(2245, 'add_to_pos', 'បន្ថែមការលក់នេះទៅអេក្រង់ម៉ាស៊ីន POS', 'Add this sale to pos screen', '加入此销售到POS萤幕', 'เพิ่มไปยังหน้าจอการขาย ณจุดขายนี้', 'Add this sale to pos screen'),
(2246, 'delete_suspended_sale', 'លុបការលក់បានបន្ទប់ | តុនេះ', 'Delete this suspended sale', '删除此暂缓销售', 'ลบการขายนี้', 'Delete this suspended sale'),
(2247, 'discount_request_failed', 'សំណើបានបរាជ័យ, មានបញ្ហាខ្លះជាមួយការបញ្ចុះតម្លៃគឺ!', 'Request Failed, There is some problem with discount!', '请求失败，折扣有一些问题！', 'คำร้องขอล้มเหลว เกิดปัญหาเกี่ยวกับส่วนลด!', 'Request Failed, There is some problem with discount!'),
(2248, 'saving', 'កំពុងរក្សាទុក...', 'Saving...', '储存中...', 'กำลังบันทึก...', 'Saving...'),
(2249, 'finalize_sale', 'បញ្ចប់លក់', 'Finalize Sale', '完成销售', 'จบ การขาย', 'Finalize Sale'),
(2250, 'cash_sale', 'ទូទាត់សាច់ប្រាក់', 'Cash Payment', '现金支付', 'ชำระด้วยเงินสด', 'Cash Payment');
INSERT INTO `aura_language` (`id`, `code`, `khmer`, `english`, `chinese`, `thai`, `vietnamese`) VALUES
(2251, 'cc_sale', 'ការទូទាត់កាតឥណទាន', 'Credit Card Payment', '信用卡支付', 'ชำระด้วยเครดิตการ์ด', 'Credit Card Payment'),
(2252, 'ch_sale', 'ការទូទាត់មូលប្បទានប័ត្រ', 'Cheque Payment', '支票支付', 'ชำระด้วยเช็ค', 'Cheque Payment'),
(2253, 'sure_to_suspend_sale', 'តើអ្នកប្រាកដជាចង់ឱ្យបន្ទប់ | តុការលក់?', 'Are you sure you want to suspend Sale?', '你确定要暂缓销售？', 'คุณต้องการระงับการขายใช่หรือไม่?', 'Are you sure you want to suspend Sale?'),
(2254, 'leave_alert', 'អ្នកនឹងបាត់បង់ទិន្នន័យការលក់ចុចយល់ព្រមដើម្បីចាកចេញហើយបោះបង់ដើម្បីស្នាក់នៅលើទំព័រនេះ។', 'You will lose sale data. Press OK to leave and Cancel to Stay on this page.', '你将失去销售资料。按OK离开，按取消停留在此页面上。', 'คุณ จะสูญเสียข้อมูลการขาย กดตกลงเพื่อออกและ ยกเลิก ที่จะอยู่ ในหน้านี้.', 'You will lose sale data. Press OK to leave and Cancel to Stay on this page.'),
(2255, 'sure_to_cancel_sale', 'តើអ្នកប្រាកដជាចង់បោះបង់ការលក់?', 'Are you sure you want to Cancel Sale?', '你确定要取消销售？', 'คุณแน่ใจหรือว่า ต้องการที่จะ ยกเลิก การขาย?', 'Are you sure you want to Cancel Sale?'),
(2256, 'sure_to_submit_sale', 'តើអ្នកប្រាកដថាអ្នកចង់រក្សាទុកការលក់?', 'Are you sure you want to Submit Sale?', '你确定要提交销售？', 'คุณแน่ใจหรือว่า ต้องการที่จะขาย?', 'Are you sure you want to Submit Sale?'),
(2257, 'alert_x_sale', 'តើអ្នកពិតជាចង់លុបការលក់បានបន្ទប់ | តុនេះឬ?', 'Are you sure you want to delete this suspended sale?', '你确定要删除这个暂缓销售？', 'คุณแน่ใจหรือว่า ต้องการลบ ระงับ การขาย นี้?', 'Are you sure you want to delete this suspended sale?'),
(2258, 'suspended_sale_deleted', 'បានលុបការលក់បានបន្ទប់ | តុដោយជោគជ័យ', 'Suspended sale successfully deleted', '暂缓销售删除成功', 'การขายถูกระงับ และลบเรียบร้อยแล้ว', 'Suspended sale successfully deleted'),
(2259, 'item_count_error', 'កំហុសមួយបានកើតឡើងខណៈពេលរាប់ធាតុសរុបនោះ សូមព្យាយាមម្តងទៀត!', 'An error occurred while counting the total items. Please try again!', '计算总品项时发生错误。请再试一次！', 'เกิดข้อผิดพลาด ขณะที่การนับรายการทั้งหมด กรุณาลองอีกครั้ง!', 'An error occurred while counting the total items. Please try again!'),
(2260, 'x_suspend', 'សូមបន្ថែមផលិតផលមុនពេលបន្ទប់ | តុការលក់នេះ សូមអរគុណ!', 'Please add product before suspending the sale. Thank you!', '请於暂缓销售前增加产品。谢谢！', 'กรุณาเพิ่ม สินค้า ก่อนที่จะ ระงับ การขาย ขอบคุณ!', 'Please add product before suspending the sale. Thank you!'),
(2261, 'x_cancel', 'មិនមានផលិតផលនោះទេគឺ សូមអរគុណ!', 'There is no product. Thank you!', '没有产品。谢谢！', 'ไม่พบสินค้า ขอบคุณ!', 'There is no product. Thank you!'),
(2262, 'no1', 'No', 'No', '否', 'ไม่', 'No'),
(2263, 'suspend', 'បន្ទប់ | តុ', 'Suspend', '暂缓', 'ระงับ', 'Suspend'),
(2264, 'order_list', 'បញ្ជីការលក់់', 'Order List', '订单列表', 'รายชื่อ การสั่งซื้อ', 'Order List'),
(2265, 'cf_display_on_bill', 'បន្ថែមបន្ថយប្រអប់ដើម្បីបង្ហាញក្នុងវិក័យប័ត្រ POS', 'Custom Field to display on pos receipt', '自定栏位显示在POS收据', 'ที่กำหนดเอง ที่จะแสดง ในใบเสร็จรับเงิน ณ จุดขาย', 'Custom Field to display on pos receipt'),
