(2388, 'all_registers_are_closed', 'បញ្ជីចុះឈ្មោះទាំងអស់ត្រូវបានបិទ', 'All registers are closed', '所有收银机已关闭', 'การลงทะเบียนทั้งหมดจะถูกปิด', 'All registers are closed'),
(2389, 'review_opened_registers', 'សូមពិនិត្យបញ្ជីបានបើកទាំងអស់នៅក្នុងតារាងខាងក្រោម', 'Please review all opened registers in table below', '请查看下表中所有打开的收银机', 'กรุณาตรวจสอบการลงทะเบียนทั้งหมดด้านล่าง', 'Please review all opened registers in table below'),
(2390, 'suspended_sale_loaded', 'ការលក់បានបន្ទប់ | តុបានផ្ទុកដោយជោគជ័យ', 'Suspended sale successfully loaded', '暂缓销售成功载入', 'โหลดการขายที่ถูกระงีบเรียบร้อยแล้ว', 'Suspended sale successfully loaded'),
(2391, 'incorrect_gift_card', 'លេខកាតអំណោយទានមិនត្រឹមត្រូវឬផុតកំណត់.', 'Gift card number is incorrect or expired.', '礼物卡号错误或已过期。', 'เลขคูปองไม่ถูกต้องหรือหมดอายุ.', 'Số thẻ giảm giá không đúng hoặc đã hết hạn.'),
(2392, 'gift_card_not_for_customer', 'លេខកាតអំណោយទានមិនមែនសម្រាប់អតិថិជននេះ.', 'Gift card number is not for this customer.', '礼物卡号不属於此客户。', 'เลขคูปองไม่ตรงกับลูกค้าท่านนี้.', 'Số thẻ giảm giá không phải là của khách hàng này.'),
(2393, 'click_to_add', 'សូមចុចប៊ូតុងខាងក្រោមដើម្បីបើក', 'Please click the button below to open', '请点击下面的按钮打开', 'กรุณาคลิกที่ ปุ่มด้านล่างเพื่อ เปิด', 'Please click the button below to open'),
(2394, 'tax_summary', 'សង្ខេបការប្រមូលពន្ធលើ', 'Tax Summary', '税金汇总', 'สรุปภาษี', 'Tax Summary'),
