(2536, 'category_code_x_exist', 'កូដប្រភេទផលិតផលមានរួចហើយ', 'Category Code does not exist.', '类别码不存在', 'ไม่มีรหัสประเภทสินค้า.', 'Mã danh mục không tồn tại.'),
(2537, 'products_added', 'បន្ថែមផលិតផលបានជោគជ័យ', 'Products (\%d) successfully added', '产品 (\%d) 加入成功', 'เพิ่มสินค้า เรียบร้อยแล้ว', 'Thêm sản phẩm thành công'),
(2538, 'product_has_attributes', 'ផលិតផលនេះមានច្រើនផ្លាស់ប្តូរុញយ', 'This product has multiple variants', '这个产品有多个选项', 'ผลิตภัณฑ์นี้มีหลายสูตร', 'Sản phẩm này có nhiều biến thể'),
(2539, 'eg_sizes_colors', 'e.g. ច្រើន ទំហំ និង / រឺ ច្រើនព៑ណ', 'e.g. Multiple Sizes and/or Colors', '例如： 多个尺寸或颜色', 'เช่น. หลาย ขนาด และ / หรือ สี', 'vd. Nhiều kích cỡ và / hoặc màu sắc'),
(2540, 'enter_attributes', 'បញ្ចូលផ្លាស់ប្តូរុញយវាញែកដោយ comma', 'Enter variants separated by comma', '用逗号分隔输入选项', 'ใส่สูตรอื่นๆคั่นด้วยเครื่องหมายจุลภาค', 'Nhập các biến thể tách bằng dấu phẩy'),
(2541, 'product_type', 'ប្រភេទផលិតផល', 'Product Type', '产品类型', 'ประเภทสินค้า', 'Loại sản phẩm'),
(2542, 'warehouse_quanitty', 'ចំនួនក្នុងឃ្លាំង', 'Warehouse Quantity', '仓库数量', 'จำนวนสินค้าที่โกดังสินค้า', 'Số lượng trong kho'),
(2543, 'product_gallery_images', 'រូបភាពផលិតផល', 'Product Gallery Images', '产品图库照片', 'อัลบั้มรูปภาพ', 'Thư viện hình ảnh sản phẩm'),
(2544, 'no_product_selected', 'គ្មានផលិតផលបានរើស សូជ្រើសរើសផលិតផលយ៉ាងតិចមួយ.', 'No Product selected', '没有产品选择。请至少选择一个产品。', 'ยังไม่ได้เลือกสินค้า. โปรดเลือกอย่างน้อย1สินค้า.', 'Không có sản phẩm được chọn. Vui lòng chọn một sản phẩm.'),
(2545, 'rack_location', 'ទីតាំងធ្នើរ', 'Rack Location', '架位', 'ที่ตั้งชั้นวางสินค้า', 'Vị trí kệ hàng'),
(2546, 'rack_set', 'បានកែតម្រូវធ្នើរផលិតផល', 'Product rack has been updated', '产品架位已经更新', 'ชั้นวางสินค้าที่ได้รับการปรับปรุง', 'Cập nhật vị trí kệ hàng thành công'),
