(2548, 'warehouse_name', 'ឈ្មោះឃ្លាំង', 'Warehouse Name', '仓库名称', 'ชื่อโกดังสินค้า', 'Tên kho hàng'),
(2549, 'no_qty_in_warehouse', 'ក្នុងឃ្លាំងមិនមានផលិតផលនេះទេ', 'Warehouse do not have this product', '仓库里没有这个产品', 'โกดังไม่มีสินค้า', 'Trong kho không có sản phẩm này'),
(2550, 'product_variants', 'Product Variants', 'Product Variants', 'Product Variants', 'Product Variants', 'Product Variants');
INSERT INTO `aura_language` (`id`, `code`, `khmer`, `english`, `chinese`, `thai`, `vietnamese`) VALUES
(2551, 'wh_pr_qty_issue', '<strong>សំណើបរាជ័យ!</strong> ឃ្លាំង និង បរិមាណផលិតផលផ្លាស់ប្តូរុញយខុស id. សូមកែតម្រូវបរិមាណសំរាប់ ឃ្លាំង និង បរិមាណផលិតផលផ្លាស់ប្តូរុញយ.', '<strong>Request Failed!</strong> Warehouse and product variants quantity id different. Please set the correct quantity for warehouse and product variants.', '<strong>请求失败!</strong> 仓库与产品数量ID不同，请设定正确的仓库及产品选项数量。', '<strong>คำร้องขอผิดพลาด!</strong> คลังสินค้า และ สินค้าที่มีหลายสูตร ไอดีไม่เหมือนกัน. กรุณาตั้งค่า ปริมาณที่ถูกต้อง สำหรับ คลังสินค้า และตัวแปร สินค้า.', '<strong>Yêu cầu thất bại!</strong> Kho và biến thể sản phẩm số lượng là khác nhau. Hãy thiết lập số lượng chính xác cho nhà kho và biến thể sản phẩm.'),
(2552, 'damages', 'ការខូចខាត', 'Damages', '坏品', 'เสียหาย', 'Hư hỏng'),
(2553, 'returns', 'វិលត្រលប់', 'Returns', '退货', 'ส่งคืน', 'Trả lại'),
(2554, 'product_qty', 'ផលិតផល', 'Product (Qty)', '产品 (数量)', 'สินค้า (จำนวน)', 'Sản phẩm (SL)'),
(2555, 'sale_reference', 'លក់យោង', 'Sale Reference', '销售参考', 'อ้างอิงการขาย', 'Số tham chiếu'),
(2556, 'product_variants_sep_by', 'ការផ្លាស់ប្តូរផលិតផលដោយញែក ពី កន្លែងបញ្ឈរ <strong>|</strong>', 'Product Variants separated by vertical bar <strong>|</strong>', '产品选项以 <strong>|</strong> 作为分隔。', 'ความหลากหลายของสินค้า แยกก้นตามแนวตั้ง <strong>|</strong>', 'Biến thể sản phẩm ngăn cách bởi thanh dọc <strong>|</strong>'),
(2557, 'not_with_variants', 'ផលិតផលគ្មានការផ្លាស់ប្តូរញយ', 'Product without variants only', '产品只能没有其他选项', 'สินค้าที่ไม่มีสูตรอื่นๆเท่านั้น', 'Sản phẩm chỉ có một biến thể'),
(2558, 'not_with_addon', NULL, 'Product without AddOn only', NULL, NULL, NULL),
(2559, 'subtraction', 'ដកចេញ', 'Subtraction', '减', 'ลบ', 'Bớt đi'),
(2560, 'quantity_adjusted', 'កែប្រែបរិមាណផលិតផលជោគជ័យ', 'Product quantity successfully adjusted', '产品数量调整成功', 'ปรับปริมาณสินค้า สำเร็จแล้ว', 'Số lượng sản phẩm được điều chỉnh thành công'),
(2561, 'label_printer', 'ម៉ាស៊ីនបោះពុម្ភ Label', 'Label Printer', '标签印表机', 'ตารางพิมพ์', 'in nhãn'),
(2562, 'product_already_has_variant', 'ផលិតផលមានការផ្លាស់ប្តូររួចរាល់', 'Product already has the variant', '产品已经有资料', 'สินค้าที่มีหลายสูตรแล้ว', 'Sản phẩm đã có các biến thể'),
(2563, 'sync_quantity', 'ការរួបរួមបរិមាណផលិតផល', 'Sync Quantity', '同步数量', 'ซิงค์จำนวน', 'Đồng bộ số lượng'),
(2564, 'products_quantity_sync', 'បរិមាណផលិតផលបានជោគជ័យក្នុងការរួបរួម', 'Product quantity successfully synchronized', '产品数量同步成功', 'ปริมาณสินค้าตรงตามที่กำหนดไว้แล้ว', 'Đồng bộ số lượng sản phẩm thành công'),
(2565, 'update_variants', 'កែប្រែផលិតផលផ្លាស់ប្តូរញយ', 'Update product variants', '更新产品选项', 'ปรับปรุงความหลากหลายของสินค้า', 'Cập nhật biến thể sản phẩm'),
(2566, 'add_more_variants', 'បន្ថែមផលិតផលផ្លាស់ប្តូរញយ', 'Add more product variants', '增加更多产品选项', 'เพิ่มรูปแบบสินค้าที่หลากหลาย', 'Thêm nhiều biến thể sản phẩm'),
(2567, 'quantity_x_adjusted', 'បរិមាណផលិតផលមិនអាចធ្វើការកែតម្រូវដោយគ្មានការទិញចូល. សូមធ្វើការទិញចូលជាមុនសិន', 'Product quantity can not be adjusted as there is no purchased item record found. Please add purchase first', '没有采购的产品无法调整数量，请先采购产品。', 'ปริมาณ สินค้า ไม่สามารถ ปรับเปลี่ยนได้ ไม่พบรายการ.กรุณาเพิ่มการซื้อสินค้าครั้งแรก', 'Số lượng sản phẩm không thể điều chỉnh vì không tìm thấy bản ghi mua hàng.. Vui lòng thêm đơn mua hàng đầu tiên'),
