(3152, 'return_sale_deleted', 'បានលុបដោយជោគជ័យការលក់ត្រឡប់មកវិញ', 'Return sale successfully deleted', '退货成功删除', 'ย้อนลบการขายสำเร็จ', 'Return sale successfully deleted'),
(3153, 'return_sale_added', 'ការលក់ត្រឡប់មកវិញបានបន្ថែមដោយជោគជ័យ', 'Return sale successfully added', '退货新增成功', 'คืนการเพิ่มการขายสำเร็จ', 'Return sale successfully added'),
(3154, 'pay_by_paypal', 'Pay by Paypal', 'Pay by Paypal', 'Paypal付款', 'จ่ายโดย Paypal', 'Pay by Paypal'),
