(3156, 'use_award_points', 'ពិន្ទុប្រើបានពានរង្វាន់', 'Use Award Points', '使用奖励点数', 'ใช้คะแนนสะสม', 'Use Award Points'),
(3157, 'use_staff_award_points', 'ពិន្ទុប្រើបានពានរង្វាន់បុគ្គលិក', 'Use Staff Award Points', '使用员工奖励点数', 'ใช้คะแนนสะสมเจ้าหน้าที่', 'Use Staff Award Points'),
(3158, 'use_points', 'ប្រើពិន្ទុ', 'Use Points', '使用点数', 'ใช้คะแนน', 'Use Points'),
(3159, 'award_points_wrong', 'សូមពិនិត្យមើលវាលបញ្ចូលពិន្ទុក្នុងការប្រើប្រាស់តម្លៃគឺខុស', 'Please check use points input field, the value is wrong.', '使用点数栏位错误，请检查使用点数栏位。', 'กรุณาตรวจคะแนนที่ใช้ในช่องที่ใส่, มีค่าผิดพลาด.', 'Please check use points input field, the value is wrong.'),
(3160, 'auto_added_for_sale_by_csv', 'បានបន្ថែមដោយស្វ័យប្រវត្តិសម្រាប់លក់ដោយ CSV', 'Automatically added for sale by csv', '自动汇入销售CSV档', 'เพิ่มการขาย csv อัตโนมัติ', 'Automatically added for sale by csv'),
(3161, 'view_gift_card', 'មើលកាតអំណោយ', 'View Gift Card', '检视礼物卡', 'ดูบัตรคูปอง', 'Xem thẻ giảm giá'),
(3162, 'card_expired', 'កាតអំណោយទានត្រូវបានផុតកំណត់រួចហើយ', 'Gift card is already expired', '礼物卡已经过期', 'บัตรคูปองนี้หมดอายุแล้ว', 'Gift card is already expired'),
(3163, 'card_is_used', 'កាតអំណោយទានពួកយើងបានប្រើរួចហើយ', 'Gift card us already used', '礼物卡已使用', 'บัตรคูปองนี้ใช้ไปแล้ว', 'Gift card us already used'),
(3164, 'no_delivery_selected', 'គ្មានគោលបំណងចែកចាយដែលបានជ្រើសរើសការអង្វរជ្រើសយ៉ាងហោចណាស់មួយលំដាប់.', 'No delivery order selected. Pleas select at least one order.', '没有选择交货单，请至少选择一个交货单', 'ไม่มีการเลือกการส่งของ. กรุณาเลือกการส่งอย่างน้อยหนึ่งรายการ.', 'No delivery order selected. Pleas select at least one order.'),
