INSERT INTO `aura_language` (`id`, `code`, `khmer`, `english`, `chinese`, `thai`, `vietnamese`) VALUES
(3701, 'overselling_will_only_work_with_AVCO_accounting_method_only', 'Overselling will only work with AVCO accounting method and the value has been changed for you.', 'Overselling will only work with AVCO accounting method and the value has been changed for you.', '超量销售只适合平均成本（AVCO）核算方法，设定值已更改。', 'การขาย จะทำงานร่วมกับ วิธีการบันทึกบัญชี AVCO และความคุ้มค่า ที่ได้รับการ เปลี่ยนแปลง สำหรับคุณ.', 'Overselling will only work with AVCO accounting method and the value has been changed for you.'),
(3702, 'accounting_method_change_alert', 'អ្នក​នឹង​ផ្លាស់​ប្តូ​រ​វិធី​សា​ស្រ្ត​គណនេយ្យ​ហើយ​វា​នឹង​រញ៉េរញ៉ៃ​ឡើង​គណនី​ចាស់​របស់​អ្នក​យើង​បាន​ស្នើ​ឱ្យ​អ្នក​ធ្វើ​ការ​នេះ​មាន​តែ​ថ្ងៃ​ទី ១ នៃ​ខែ​ណាមួយ​ទេ​.', 'You are going to change the accounting method and it will mess up your old account. We suggest you to do this only on 1st day of any month.', '你将要改变会计核算方法，这个动作将会弄乱你的旧账。建议只能在每月的第一天变更。', 'คุณ กำลังจะเปลี่ยน วิธีการบันทึกบัญชีเก่าของคุณ. เราขอแนะนำให้ คุณทำเช่นนี้เพียง แค่ใน วันที่ 1 ของทุกเดือน.', 'You are going to change the accounting method and it will mess up your old account. We suggest you to do this only on 1st day of any month.'),
(3703, 'setting_updated', 'ការ​កំណត់​ធ្វើ​កែសម្រួលបាន​ជោគជ័យ​', 'Settings successfully updated', '设定更新成功', 'การตั้งค่าการปรับปรุง', 'Cập nhật cài đặt thành công'),
(3704, 'logo_uploaded', 'Logo ​ផ្ទុក​ឡើង​ដោយ​ជោគជ័យ​', 'Logo successfully uploaded', 'Logo更新成功', 'โลโก้ที่อัปโหลดที่ประสบความสำเร็จ', 'Tải lên logo thành công'),
