INSERT INTO `aura_theme_banners` (`id`, `biller_id`, `position`, `title`, `subtitle`, `image`, `link_url`, `button_text`, `sort_order`, `start_date`, `end_date`, `status`, `created_at`, `badge`, `badge_color`, `badge_bg`, `coupon_code`, `original_price`, `promo_price`, `savings`, `valid_until`, `accent_color`, `overlay_gradient`) VALUES
(1, 3, 'home_promo', 'Spanish Iced Latte & Almond Croissant', 'Signature single-origin espresso with sweetened milk paired with flaky 84% butter pastry.', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=800&auto=format&fit=crop&q=80', '/shop/sbc-store', 'Claim 25% Off Deal', 1, NULL, NULL, 1, '2026-10-15 12:22:04', 'DAILY FLASH DEAL • 25% OFF', '#ef4444', 'rgba(239, 68, 68, 0.95)', 'AURACOFFEE25', 12.25, 8.99, 'Save $3.26', 'Today only until 3:00 PM', '#2F6FED', NULL),
(2, 251, 'home_promo', 'Golden Viennoiserie & Sourdough Box', 'Warm Normandy butter croissants, pain au chocolat, and rustic country sourdough loaves.', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&auto=format&fit=crop&q=80', '/shop/aura-bakery', 'Claim Bakery Deal', 2, NULL, NULL, 1, '2026-10-15 12:22:04', 'WEEKEND SPECIAL • BUY 1 GET 1 50% OFF', '#f59e0b', 'rgba(245, 158, 11, 0.95)', 'BAKERY50', 18.50, 12.75, 'Save $5.75', 'Fresh morning bake', '#FF7A3D', NULL),
(3, 252, 'home_promo', 'Kyoto Uji Matcha Latte & Mochi Waffle', 'First-harvest ceremonial matcha stone-ground in Uji, whisked fresh with oat milk.', 'https://images.unsplash.com/photo-1536256263959-770b48d82b0a?w=800&auto=format&fit=crop&q=80', '/shop/aura-lounge', 'Explore Matcha Deal', 3, NULL, NULL, 1, '2026-10-15 12:22:04', 'CEREMONIAL SPECIAL • 20% OFF', '#10b981', 'rgba(16, 185, 129, 0.95)', 'MATCHA20', 14.00, 10.50, 'Save $3.50', 'Available daily 11am-8pm', '#10b981', NULL),
(4, 253, 'home_promo', 'Wagyu Truffle Burger & Hand-Cut Fries', 'Aged gruyère cheese, black truffle aioli, and caramelized balsamic onion jam on brioche.', 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=800&auto=format&fit=crop&q=80', '/shop/aura-bistro', 'Order Bistro Combo', 4, NULL, NULL, 1, '2026-10-15 12:22:04', 'CHEF\'S SPECIAL • $5 DISCOUNT', '#8b5cf6', 'rgba(139, 92, 246, 0.95)', 'BISTROVIP', 19.50, 14.50, 'Save $5.00', 'Dinner & lunch service', '#8b5cf6', NULL),
(5, 0, 'home_hero', 'Global B2B Sourcing Fair: Factory-Direct Commercial Machinery', 'Container-load discounts on dual-boiler espresso machinery, planetary mixers & POS terminals with ISO 9001 compliance.', 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?w=1400&auto=format&fit=crop&q=80', NULL, NULL, 0, NULL, NULL, 1, '2026-10-15 13:21:27', '🏭 FACTORY DIRECT • UP TO 35% OFF', NULL, NULL, 'ALIBABA35', NULL, NULL, NULL, NULL, NULL, NULL),
(6, 0, 'home_hero', 'Certified Biodegradable & Sugarcane Bagasse Eco-Packaging', 'Full-container wholesale orders with custom logo debossing and free shipping on bulk cafe carton pallets.', 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?w=1400&auto=format&fit=crop&q=80', NULL, NULL, 0, NULL, NULL, 1, '2026-10-15 13:21:27', '🌿 ECO DISPOSABLES • BULK WHOLESALE', NULL, NULL, 'ECOPACK2026', NULL, NULL, NULL, NULL, NULL, NULL);
