INSERT INTO `aura_theme_posts` (`id`, `biller_id`, `title`, `slug`, `excerpt`, `body`, `image`, `status`, `published_at`, `created_at`, `category`, `badge`, `duration`, `author`, `views`) VALUES
(1, 1, 'B2B Procurement & Contract Sourcing', 'b2b-procurement-contract-sourcing', 'Master wholesale RFQs, volume tier pricing structures, payment escrow terms, and commercial dispute resolution.', 'Complete procurement guide for corporate supply managers. Covers verified factory audits, container freight logistics, proforma invoices, and payment escrow mechanisms.', NULL, 0, NULL, '2026-10-15 12:22:25', 'Core Program', 'Core Program', '8 Modules • 4 Hours', 'Aura Trade Council', 0),
(2, 1, 'Multi-Store Setup & Telegram E-Menu Dispatch', 'multi-store-setup-telegram-emenu', 'Step-by-step tutorial on @BotFather integration, table QR code setup, menu category tagging, and automated kitchen routing.', 'Deploy your Telegram Mini App contactless ordering in under 48 hours. Includes table QR generator, staff channel routing, and instant receipt printing setup.', NULL, 0, NULL, '2026-10-15 12:22:25', 'E-Menu System', 'E-Menu System', '6 Modules • 2.5 Hours', 'Hospitality Tech Lead', 0),
(3, 1, 'Factory Audits & ISO/HACCP Quality Compliance', 'factory-audits-quality-compliance', 'Guidelines for food safety certifications, direct-trade farm lot traceability, electronics warranty standards, and packaging integrity.', 'Comprehensive guide to international food safety and manufacturing standards, batch traceability, and pre-shipment quality inspection protocols.', NULL, 0, NULL, '2026-10-15 12:22:25', 'Compliance', 'Compliance', '5 Modules • 3 Hours', 'Quality Assurance Board', 0),
(4, 1, 'Cross-Border Freight & Customs IncoTerms', 'cross-border-freight-customs-incoterms', 'Understanding FOB vs CIF terms, overland transit between Cambodia and Thailand, port handling, and import tax clearance.', 'Practical guide to regional overland and port transit across Cambodia, Thailand, and Vietnam. Learn customs declarations, tax rates, and delivery logistics.', NULL, 0, NULL, '2026-10-15 12:22:25', 'Logistics', 'Logistics', '7 Modules • 3.5 Hours', 'Regional Freight Directorate', 0),
(5, 1, 'The Art of Pour-Over Coffee in Southeast Asia', 'art-of-pour-over-coffee', 'Discover the precise grind sizes, water temperatures, and filter techniques that bring out highland floral notes.', 'Exploring single-origin Arabica extraction methods, water chemistry, and bloom techniques that highlight natural floral and honey flavors.', NULL, 0, NULL, '2026-10-15 12:22:25', 'Brewing Guide', 'Brewing Guide', '15 min read', 'Chantha Keo', 0);
