CREATE DEFINER=`root`@`localhost` FUNCTION `aura_user_can` (`p_user_id` INT UNSIGNED, `p_key` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci) RETURNS TINYINT(1) READS SQL DATA BEGIN
  DECLARE v_group   INT DEFAULT NULL;
  DECLARE v_status  VARCHAR(20) DEFAULT NULL;
  DECLARE v_role    VARCHAR(50) DEFAULT NULL;
  DECLARE v_level   INT DEFAULT NULL;
  DECLARE v_effect  VARCHAR(10) DEFAULT NULL;
  DECLARE v_allowed TINYINT DEFAULT NULL;

  -- 1. Load user context
  SELECT group_id, status, role, level
    INTO v_group, v_status, v_role, v_level
    FROM aura_users
   WHERE id = p_user_id AND deleted_at IS NULL;

  IF v_status IS NULL OR v_status <> 'active' THEN
    RETURN 0;
  END IF;

  -- 2. Super admin short-circuit
  IF v_role = 'super_admin' OR v_level = 1 THEN
    RETURN 1;
  END IF;

  -- 3. Per-user explicit override wins first
  SELECT effect INTO v_effect
    FROM aura_user_permissions
   WHERE user_id = p_user_id AND permission_key = p_key
   LIMIT 1;

  IF v_effect = 'deny'  THEN RETURN 0; END IF;
  IF v_effect = 'allow' THEN RETURN 1; END IF;

  -- 4. Fall back to group-level permission
  SELECT allowed INTO v_allowed
    FROM aura_group_permissions
   WHERE group_id = v_group AND permission_key = p_key
   LIMIT 1;

  RETURN COALESCE(v_allowed, 0);
END$$

