-- Triggers `aura_att_check_in_out`
--
DROP TRIGGER IF EXISTS `deleteCheckInOut`;
DELIMITER $$
CREATE TRIGGER `deleteCheckInOut` AFTER DELETE ON `aura_att_check_in_out` FOR EACH ROW BEGIN 
       DELETE FROM aura_att_dailies WHERE check_in_out_id = OLD.id;
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `insertCheckInOut`;
DELIMITER $$
CREATE TRIGGER `insertCheckInOut` AFTER INSERT ON `aura_att_check_in_out` FOR EACH ROW BEGIN
          CALL check_in_out(NEW.id,NEW.employee_id,NEW.check_time);

END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `updateCheckInOut`;
DELIMITER $$
CREATE TRIGGER `updateCheckInOut` AFTER UPDATE ON `aura_att_check_in_out` FOR EACH ROW BEGIN 
         DELETE FROM aura_att_dailies WHERE check_in_out_id = NEW.id;
         CALL check_in_out(NEW.id,NEW.employee_id,NEW.check_time);
END
$$
DELIMITER ;

