DROP TRIGGER IF EXISTS `deleteStock`;
DELIMITER $$
CREATE TRIGGER `deleteStock` AFTER DELETE ON `aura_stock_movement` FOR EACH ROW BEGIN
	SET @total_qty = ( SELECT SUM( quantity ) AS qoh FROM aura_stock_movement WHERE product_id = OLD.product_id );
	SET @total_weight = ( SELECT SUM(weight) AS weight FROM aura_stock_movement WHERE product_id = OLD.product_id );
	UPDATE aura_products 
		SET quantity = IFNULL(@total_qty, 0), weight = IFNULL(@total_weight, 0)
	WHERE
		id = OLD.product_id;
	
	SET @qty = ( SELECT SUM( quantity ) AS qoh FROM aura_stock_movement WHERE product_id = OLD.product_id AND warehouse_id = OLD.warehouse_id );
	SET @weight = ( SELECT SUM( weight ) AS weight FROM aura_stock_movement WHERE product_id = OLD.product_id AND warehouse_id = OLD.warehouse_id );

	UPDATE aura_warehouses_products 
		SET quantity = IFNULL(@qty, 0), weight = IFNULL(@weight, 0)
	WHERE
		product_id = OLD.product_id 
		AND warehouse_id = OLD.warehouse_id;
	IF
		( OLD.option_id > 0 ) THEN
			
			SET @opt_qty = (
				SELECT
					SUM( quantity ) AS qoh 
				FROM
					aura_stock_movement 
				WHERE
					product_id = OLD.product_id 
					AND warehouse_id = OLD.warehouse_id 
					AND option_id = OLD.option_id 
			);

			SET @opt_weight = (
				SELECT
					SUM( weight ) AS weight 
				FROM
					aura_stock_movement 
				WHERE
					product_id = OLD.product_id 
					AND warehouse_id = OLD.warehouse_id 
					AND option_id = OLD.option_id 
			);
		UPDATE aura_warehouses_products_variants 
			SET quantity = IFNULL(@opt_qty, 0), weight = IFNULL(@opt_weight, 0)
		WHERE
			product_id = OLD.product_id 
			AND warehouse_id = OLD.warehouse_id 
			AND option_id = OLD.option_id;
		
	END IF;
	IF
		( OLD.serial_no <> '' ) THEN
		IF
			EXISTS ( SELECT product_id FROM aura_product_serials WHERE product_id = OLD.product_id AND warehouse_id = OLD.warehouse_id AND serial = OLD.serial_no ) THEN
				
				SET @old_serial_qty = (
				SELECT
					SUM( quantity ) AS qoh 
				FROM
					aura_stock_movement 
				WHERE
					product_id = OLD.product_id 
					AND warehouse_id = OLD.warehouse_id 
					AND serial_no = OLD.serial_no 
				);
			IF
				( @old_serial_qty < 0 ) THEN
					
					SET @inaction = 1;
				ELSE 
					SET @inaction = 0;
				
			END IF;
			UPDATE aura_product_serials 
			SET inactive = @inaction 
			WHERE
				product_id = OLD.product_id 
				AND warehouse_id = OLD.warehouse_id 
				AND serial = OLD.serial_no;
			
		END IF;
		
	END IF;

END
$$
