				( NEW.product_id, NEW.warehouse_id, @opt_qty,@opt_weight, NEW.option_id );
			
		END IF;
		
	END IF;
	
	SET @total_qty_old = ( SELECT SUM( quantity ) AS qoh FROM aura_stock_movement WHERE product_id = OLD.product_id );
	SET @total_weight_old = ( SELECT SUM( weight ) AS weight FROM aura_stock_movement WHERE product_id = OLD.product_id );

	UPDATE aura_products 
	SET quantity = @total_qty_old, weight = @total_weight_old
	WHERE
		id = OLD.product_id;
	
	SET @qty_old = ( SELECT SUM( quantity ) AS qoh FROM aura_stock_movement WHERE product_id = OLD.product_id AND warehouse_id = OLD.warehouse_id );
	SET @weight_old = ( SELECT SUM( weight ) AS weight FROM aura_stock_movement WHERE product_id = OLD.product_id AND warehouse_id = OLD.warehouse_id );

	UPDATE aura_warehouses_products 
		SET quantity = IFNULL(@qty_old, 0),weight = IFNULL(@weight_old, 0)
	WHERE
		product_id = OLD.product_id 
		AND warehouse_id = OLD.warehouse_id;
	IF
		( OLD.option_id > 0 ) THEN
			
			SET @opt_qty_old = (
				SELECT
					SUM( quantity ) AS qoh 
				FROM
					aura_stock_movement 
				WHERE
					product_id = OLD.product_id 
					AND warehouse_id = OLD.warehouse_id 
					AND option_id = OLD.option_id 
			);

			SET @opt_weight_old = (
				SELECT
					SUM( weight ) AS weight 
				FROM
					aura_stock_movement 
				WHERE
					product_id = OLD.product_id 
					AND warehouse_id = OLD.warehouse_id 
					AND option_id = OLD.option_id 
			);
		UPDATE aura_warehouses_products_variants 
			SET quantity = IFNULL(@opt_qty_old, 0),weight = IFNULL(@opt_weight_old, 0)
		WHERE
			product_id = OLD.product_id 
			AND warehouse_id = OLD.warehouse_id 
			AND option_id = OLD.option_id;
		
	END IF;
	IF
		( NEW.serial_no <> '' ) THEN
		IF
			EXISTS ( SELECT product_id FROM aura_product_serials WHERE product_id = NEW.product_id AND warehouse_id = NEW.warehouse_id AND serial = NEW.serial_no ) THEN
				
				SET @serial_qty = (
					SELECT
						SUM( quantity ) AS qoh 
					FROM
						aura_stock_movement 
					WHERE
						product_id = NEW.product_id 
						AND warehouse_id = NEW.warehouse_id 
						AND serial_no = NEW.serial_no 
				);
			IF
				( @serial_qty < 0 ) THEN
					
					SET @inaction = 1;
				ELSE 
					SET @inaction = 0;
				
			END IF;
			UPDATE aura_product_serials 
				SET inactive = @inaction 
			WHERE
				product_id = NEW.product_id 
				AND warehouse_id = NEW.warehouse_id 
				AND serial = NEW.serial_no;
			
		END IF;
		
	END IF;
	IF
		( OLD.serial_no <> '' ) THEN
		IF
			EXISTS ( SELECT product_id FROM aura_product_serials WHERE product_id = OLD.product_id AND warehouse_id = OLD.warehouse_id AND serial = OLD.serial_no ) THEN
				
				SET @old_serial_qty = (
					SELECT
						SUM( quantity ) AS qoh 
					FROM
						aura_stock_movement 
					WHERE
						product_id = OLD.product_id 
						AND warehouse_id = OLD.warehouse_id 
						AND serial_no = OLD.serial_no 
				);
			IF
				( @old_serial_qty < 0 ) THEN
					
					SET @inaction = 1;
				ELSE 
					SET @inaction = 0;
				
			END IF;
			UPDATE aura_product_serials 
			SET inactive = @inaction 
			WHERE
				product_id = OLD.product_id 
				AND warehouse_id = OLD.warehouse_id 
				AND serial = OLD.serial_no;
			
		END IF;
		
	END IF;

END
$$
DELIMITER ;

